mapper.select:
SELECT r.id AS id, r.hazard_code AS hazardCode, r.flow_code AS flowCode, r.problem_source AS problemSource, r.check_name AS checkName, r.plant_id AS plantId, r.area_id AS areaId, r.location_id AS locationId, r.problem_level AS problemLevel, r.status AS status, r.check_time AS checkTime, r.hazard_category AS hazardCategory, r.create_time AS createTime, fm.field_name AS plantName, fm1.field_name AS areaName, sdi.item_name AS problemCategoryName, li.location_name AS locationName, hd.problem_description AS problemDescription FROM ytsafety_hazard_report r LEFT JOIN safety_field_manage fm ON r.plant_id = fm.id AND fm.delete_falg = 0 LEFT JOIN safety_field_manage fm1 ON r.area_id = fm1.id AND fm1.delete_falg = 0 LEFT JOIN safety_dict_item sdi ON r.problem_category = sdi.id LEFT JOIN ytsafety_location_info li ON r.location_id = li.id LEFT JOIN ( SELECT process_id, ANY_VALUE(problem_description) AS problem_description FROM ytsafety_hazard_description GROUP BY process_id ) hd ON r.id = hd.process_id WHERE r.del_flag = 0 and r.draft_status = 0 and r.create_user = #{empNo}
AND ( r.check_name LIKE CONCAT('%', #{screeningCondition}, '%') OR (r.problem_source = 'COMPANY_INSPECTION' AND '公司级检查' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.problem_source = 'DEPARTMENT_SELF_CHECK' AND '部门自查' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.problem_source = 'EMPLOYEE_SNAPSHOT' AND '员工随手拍' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.problem_source = 'PATROL_EXCEPTION' AND '巡查异常' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.problem_level = 1 AND '低' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.problem_level = 2 AND '一般' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.problem_level = 3 AND '较大' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.problem_level = 4 AND '重大' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.status = 0 AND '草稿' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.status = 1 AND '审批中' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.status = 2 AND '整改中' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.status = 3 AND '验证中' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.status = 4 AND '部分完成' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.status = 5 AND '已完成' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.status = 6 AND '预期未完成' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.status = 7 AND '逾期完成' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.status = 8 AND '延期审批中' LIKE CONCAT('%', #{screeningCondition}, '%')) OR (r.status = 30 AND '废弃' LIKE CONCAT('%', #{screeningCondition}, '%')) OR fm.field_name LIKE CONCAT('%', #{screeningCondition}, '%') OR li.location_name LIKE CONCAT('%', #{screeningCondition}, '%') OR hd.problem_description LIKE CONCAT('%', #{screeningCondition}, '%') )
ORDER BY r.create_time DESC

SELECT r.id AS id, r.hazard_code AS hazardCode, r.hazard_category AS hazardCategory, CASE r.hazard_category WHEN 1 THEN '消防' WHEN 2 THEN '治安' ELSE '' END AS hazardCategoryText, r.problem_source AS problemSource, CASE r.problem_source WHEN 'COMPANY_INSPECTION' THEN '公司级检查' WHEN 'DEPARTMENT_SELF_CHECK' THEN '部门自查' WHEN 'EMPLOYEE_SNAPSHOT' THEN '员工随手拍' WHEN 'PATROL_EXCEPTION' THEN '巡查异常' ELSE '' END AS problemSourceText, r.problem_category AS problemCategory, di.item_name AS problemCategoryText, r.problem_level AS problemLevel, CASE r.problem_level WHEN 2 THEN '一般' WHEN 3 THEN '较大' WHEN 4 THEN '重大' END AS problemLevelText, r.is_immediate_handle AS isImmediateHandle, CASE r.is_immediate_handle WHEN 1 THEN '是' ELSE '否' END AS isImmediateHandleText, r.apply_name AS applyName, r.rectify_person_emp_no AS rectifyPersonEmpNo, emp_rectify.emp_name AS rectifyPersonName, r.check_time AS checkTime, r.plant_id AS plantId, fm.field_name AS plantName, r.area_id AS areaId, sfm.field_name AS areaName, r.org_id AS orgId, r.org_path_name AS orgName, r.location_id AS locationId, li.location_name AS locationName, r.rectify_deadline AS rectifyDeadline, r.rectify_delay_time AS rectifyDelayTime, r.cc_person_emp_no AS ccPersonEmpNo, r.rectify_complete_time AS rectifyCompleteTime, r.status AS status, CASE r.status WHEN 0 THEN '草稿' WHEN 1 THEN '审批中' WHEN 2 THEN '整改中' WHEN 3 THEN '验证中' WHEN 4 THEN '部分完成' WHEN 5 THEN '已完成' WHEN 6 THEN '预期未完成' WHEN 7 THEN '逾期完成' WHEN 8 THEN '延期审批中' WHEN 9 THEN '起草' WHEN 30 THEN '废弃' ELSE '' END AS statusText, r.create_time AS createTime, IFNULL(desc_agg.problem_photos, '') AS problemPhotos, IFNULL(desc_agg.problem_description, '') AS problemDescription, IFNULL(result_agg.rectify_result, '') AS rectifyResult, IFNULL(result_agg.complete_photos, '') AS completePhotos FROM ytsafety_hazard_report r LEFT JOIN safety_field_manage fm ON r.plant_id = fm.id AND fm.delete_falg = 0 LEFT JOIN safety_field_manage sfm ON r.area_id = sfm.id AND sfm.delete_falg = 0 LEFT JOIN ytsafety_location_info li ON r.location_id = li.id LEFT JOIN safety_dict_item di ON r.problem_category = di.id LEFT JOIN safety_employee_message emp_rectify ON r.rectify_person_emp_no = emp_rectify.emp_no LEFT JOIN ( SELECT process_id, GROUP_CONCAT(problem_description ORDER BY id SEPARATOR '; ') AS problem_description, GROUP_CONCAT(attachment_ids ORDER BY id SEPARATOR ',') AS problem_photos FROM ytsafety_hazard_description GROUP BY process_id ) desc_agg ON r.id = desc_agg.process_id LEFT JOIN ( SELECT process_id, GROUP_CONCAT(handle_measure ORDER BY id SEPARATOR '; ') AS rectify_result, GROUP_CONCAT(attachment_ids ORDER BY id SEPARATOR ',') AS complete_photos FROM ytsafety_hazard_result GROUP BY process_id ) result_agg ON r.id = result_agg.process_id WHERE r.del_flag = 0
AND (r.status != 0 OR r.apply_no = #{query.applyNo})
AND r.hazard_code = #{query.hazardCode}
AND r.hazard_category = #{query.hazardCategory}
AND r.problem_source = #{query.problemSource}
AND r.problem_level = #{query.problemLevel}
AND r.plant_id = #{query.plantId}
AND r.area_id = #{query.areaId}
AND r.location_id = #{query.locationId}
AND li.location_name = #{query.locationName}
AND r.org_id = #{query.orgId}
AND r.rectify_person_emp_no = #{query.rectifyPersonEmpNo}
AND r.problem_category LIKE CONCAT('%', #{query.problemCategory}, '%')
AND desc_agg.problem_description LIKE CONCAT('%', #{query.problemDescription}, '%')
AND r.is_immediate_handle = #{query.isImmediateHandle}
AND r.status = #{query.status} AND (r.rectify_delay_time IS NULL OR r.rectify_delay_time > NOW())
AND (r.status = 6 OR (r.status != 0 AND r.status != 5 AND r.status != 7 AND r.status != 9 AND r.status != 30 AND r.rectify_delay_time < NOW()))
AND r.status = #{query.status}
AND DATE(r.check_time) BETWEEN #{query.checkTimeBegin} AND #{query.checkTimeEnd}
ORDER BY r.create_time DESC

SELECT r.id AS id, r.hazard_code AS hazardCode, r.hazard_category AS hazardCategory, CASE r.hazard_category WHEN 1 THEN '消防' WHEN 2 THEN '治安' ELSE '' END AS hazardCategoryText, r.problem_source AS problemSource, CASE r.problem_source WHEN 'COMPANY_INSPECTION' THEN '公司级检查' WHEN 'DEPARTMENT_SELF_CHECK' THEN '部门自查' WHEN 'EMPLOYEE_SNAPSHOT' THEN '员工随手拍' WHEN 'PATROL_EXCEPTION' THEN '巡查异常' ELSE '' END AS problemSourceText, r.problem_category AS problemCategory, di.item_name AS problemCategoryText, r.problem_level AS problemLevel, CASE r.problem_level WHEN 2 THEN '一般' WHEN 3 THEN '较大' WHEN 4 THEN '重大' END AS problemLevelText, r.is_immediate_handle AS isImmediateHandle, CASE r.is_immediate_handle WHEN 1 THEN '是' ELSE '否' END AS isImmediateHandleText, r.apply_name AS applyName, r.rectify_person_emp_no AS rectifyPersonEmpNo, emp_rectify.emp_name AS rectifyPersonName, r.check_time AS checkTime, r.plant_id AS plantId, fm.field_name AS plantName, r.area_id AS areaId, sfm.field_name AS areaName, r.org_id AS orgId, r.org_path_name AS orgName, r.location_id AS locationId, li.location_name AS locationName, r.rectify_deadline AS rectifyDeadline, r.rectify_delay_time AS rectifyDelayTime, r.cc_person_emp_no AS ccPersonEmpNo, r.rectify_complete_time AS rectifyCompleteTime, r.status AS status, CASE r.status WHEN 0 THEN '草稿' WHEN 1 THEN '审批中' WHEN 2 THEN '整改中' WHEN 3 THEN '验证中' WHEN 4 THEN '部分完成' WHEN 5 THEN '已完成' WHEN 6 THEN '预期未完成' WHEN 7 THEN '逾期完成' WHEN 8 THEN '延期审批中' WHEN 9 THEN '起草' WHEN 30 THEN '废弃' ELSE '' END AS statusText, r.create_time AS createTime, IFNULL(desc_agg.problem_photos, '') AS problemPhotos, IFNULL(desc_agg.problem_description, '') AS problemDescription, IFNULL(result_agg.rectify_result, '') AS rectifyResult, IFNULL(result_agg.complete_photos, '') AS completePhotos FROM ytsafety_hazard_report r LEFT JOIN safety_field_manage fm ON r.plant_id = fm.id AND fm.delete_falg = 0 LEFT JOIN safety_field_manage sfm ON r.area_id = sfm.id AND sfm.delete_falg = 0 LEFT JOIN ytsafety_location_info li ON r.location_id = li.id LEFT JOIN safety_dict_item di ON r.problem_category = di.id LEFT JOIN safety_employee_message emp_rectify ON r.rectify_person_emp_no = emp_rectify.emp_no LEFT JOIN ( SELECT process_id, GROUP_CONCAT(problem_description ORDER BY id SEPARATOR '; ') AS problem_description, GROUP_CONCAT(attachment_ids ORDER BY id SEPARATOR ',') AS problem_photos FROM ytsafety_hazard_description GROUP BY process_id ) desc_agg ON r.id = desc_agg.process_id LEFT JOIN ( SELECT process_id, GROUP_CONCAT(handle_measure ORDER BY id SEPARATOR '; ') AS rectify_result, GROUP_CONCAT(attachment_ids ORDER BY id SEPARATOR ',') AS complete_photos FROM ytsafety_hazard_result GROUP BY process_id ) result_agg ON r.id = result_agg.process_id WHERE r.del_flag = 0
AND (r.status != 0 OR r.apply_no = #{query.applyNo})
AND r.id IN
#{id}
AND r.hazard_code = #{query.hazardCode}
AND r.hazard_category = #{query.hazardCategory}
AND r.problem_source = #{query.problemSource}
AND r.problem_level = #{query.problemLevel}
AND r.plant_id = #{query.plantId}
AND r.area_id = #{query.areaId}
AND r.location_id = #{query.locationId}
AND li.location_name = #{query.locationName}
AND r.org_id = #{query.orgId}
AND r.rectify_person_emp_no = #{query.rectifyPersonEmpNo}
AND r.problem_category LIKE CONCAT('%', #{query.problemCategory}, '%')
AND desc_agg.problem_description LIKE CONCAT('%', #{query.problemDescription}, '%')
AND r.is_immediate_handle = #{query.isImmediateHandle}
AND r.status = #{query.status} AND (r.rectify_delay_time IS NULL OR r.rectify_delay_time > NOW())
AND (r.status = 6 OR (r.status != 0 AND r.status != 5 AND r.status != 7 AND r.status != 9 AND r.status != 30 AND r.rectify_delay_time < NOW()))
AND r.status = #{query.status}
AND DATE(r.check_time) BETWEEN #{query.checkTimeBegin} AND #{query.checkTimeEnd}
ORDER BY r.create_time DESC
